import re

def run(data: dict) -> dict:
    csv_text = data.get("csv", "")
    required_headers = data.get("required_headers", [])
    missing_headers = []
    found_headers = []
    is_valid = True

    if not csv_text:
        return {"missing_headers": missing_headers, "found_headers": found_headers, "is_valid": is_valid}

    lines = csv_text.splitlines()
    if len(lines) < 2:
        return {"missing_headers": missing_headers, "found_headers": found_headers, "is_valid": is_valid}

    header_row = lines[0]
    headers = re.split(r',\s*', header_row)

    for header in required_headers:
        if header in headers:
            found_headers.append(header)
        else:
            missing_headers.append(header)
            is_valid = False

    return {"missing_headers": missing_headers, "found_headers": found_headers, "is_valid": is_valid}

